int validate_stream_offset(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    size_t min_size = h->min_size;
    size_t dir_length = sst->dir_length;
    const char *stream_start = (const char *)sst->data;
    const char *stream_end = stream_start + dir_length;
    const char *check_start = (const char *)p - tail;
    const char *check_end = (const char *)p;

    if (check_start < stream_start || check_end > stream_end) {
        errno = EFTYPE;
        fprintf(stderr, "Invalid stream offset at line %d: check range [%p, %p) is outside valid stream range [%p, %p)\n",
                line, (void *)check_start, (void *)check_end, (void *)stream_start, (void *)stream_end);
        return -1;
    }

    return 0;
}

int check_stream_offset_validity(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    size_t stream_start = (size_t)sst;
    size_t stream_end = stream_start + h->min_stream_size + sst->dir_length;
    size_t data_start = (size_t)p;
    size_t data_end = data_start + tail;

    if (data_start < stream_start || data_end > stream_end) {
        errno = EFTYPE;
        // Debug output can be added here if necessary
        return -1;
    }

    return 0;
}

int check_offset_validity(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    size_t stream_start = (size_t)sst;
    size_t stream_end = stream_start + h->min_size + sst->dir_length;
    size_t check_start = (size_t)p;
    size_t check_end = check_start + tail;

    if (check_start < stream_start || check_end > stream_end) {
        errno = EFTYPE;
        fprintf(stderr, "Invalid offset check at line %d: start=0x%zx, end=0x%zx, stream=[0x%zx, 0x%zx)\n",
                line, check_start, check_end, stream_start, stream_end);
        return -1;
    }

    return 0;
}

int check_stream_offset(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    size_t min_size = h->min_size;
    size_t dir_len = sst->dir_len;
    const char *start = (const char *)sst->data;
    const char *end = (const char *)p + tail;

    if ((size_t)(end - start) > dir_len + min_size) {
        errno = EFTYPE;
        fprintf(stderr, "Invalid stream offset at line %d: end=%zu, dir_len=%zu, min_size=%zu\n",
                line, (size_t)(end - start), dir_len, min_size);
        return -1;
    }

    return 0;
}
